typeScriptFunctionUsageExample:
import { isOfType } from "@type-check/guards";

const input: unknown = Math.random() > 0.5 ? 123 : "hello";

if (isOfType(input, "number")) {
  // input is a number here
  const doubled = input * 2;
  console.log(doubled);
} else if (isOfType(input, "string")) {
  // input is a string here
  console.log(input.toUpperCase());
}

console.log(isOfType(null, "null"));
console.log(isOfType(undefined, "undefined"));

typeScriptObjectUsageExample:
import { isOfType } from "@type-check/guards";

type Payload = { id: unknown; meta: unknown };

function normalize(payload: Payload) {
  const id = isOfType(payload.id, "string") ? payload.id : "";
  const metaIsObject = isOfType(payload.meta, "object");

  return {
    id,
    hasMetaObject: metaIsObject
  };
}

console.log(normalize({ id: 42, meta: { source: "api" } }));
